## ars.R
##
## Adaptive Rejection Sampling (ARS) for univariate log-concave densities,
## following Gilks, W. R., & Wild, P. (1992). "Adaptive Rejection Sampling
## for Gibbs Sampling." Journal of the Royal Statistical Society: Series C
## (Applied Statistics), 41(2), 337-348.
##
## Public API:
##   ars(n, f, lower, upper, initial_points, tol, max_iter, seed)  -- sampler
##   test()                                                        -- test suite
##
## Internal helpers are prefixed with ".ars_" and are organized by the
## discrete task they perform (validation, log-density evaluation,
## initial-abscissae search, log-concavity checking, hull construction,
## hull evaluation, and hull sampling).

## =================================================================
## 1. Input validation
## =================================================================

.ars_validate_inputs <- function(n, f, lower, upper, initial_points, max_iter, tol) {
  if (!is.function(f)) {
    stop("ars: 'f' must be a function that computes the (possibly unnormalized) density, vectorized over its first argument.")
  }
  if (!is.numeric(n) || length(n) != 1 || is.na(n) || n != round(n) || n <= 0) {
    stop("ars: 'n' (number of samples) must be a single positive integer.")
  }
  if (!is.numeric(lower) || length(lower) != 1 || is.na(lower)) {
    stop("ars: 'lower' must be a single numeric value (possibly -Inf).")
  }
  if (!is.numeric(upper) || length(upper) != 1 || is.na(upper)) {
    stop("ars: 'upper' must be a single numeric value (possibly Inf).")
  }
  if (lower >= upper) {
    stop("ars: invalid domain -- 'lower' must be strictly less than 'upper'.")
  }
  if (!is.null(initial_points)) {
    if (!is.numeric(initial_points) || length(initial_points) < 2) {
      stop("ars: 'initial_points' must be a numeric vector with at least 2 points.")
    }
    if (any(is.na(initial_points))) {
      stop("ars: 'initial_points' must not contain NA/NaN.")
    }
    if (any(initial_points <= lower) || any(initial_points >= upper)) {
      stop("ars: all 'initial_points' must lie strictly within (lower, upper).")
    }
  }
  if (!is.numeric(max_iter) || length(max_iter) != 1 || is.na(max_iter) || max_iter <= 0) {
    stop("ars: 'max_iter' must be a single positive number.")
  }
  if (!is.numeric(tol) || length(tol) != 1 || is.na(tol) || tol <= 0) {
    stop("ars: 'tol' must be a single positive number.")
  }
  invisible(TRUE)
}

## =================================================================
## 2. Log-density and numerical derivative
## =================================================================

## Wraps the user-supplied (possibly unnormalized) density 'f' into a
## log-density function h(x) = log(f(x)), with basic sanity checking.
.ars_make_log_density <- function(f) {
  function(x) {
    fx <- f(x)
    if (!is.numeric(fx) || length(fx) != length(x)) {
      stop("ars: the density function must return a numeric vector of the same length as its input.")
    }
    if (any(is.na(fx))) {
      stop("ars: the density function returned NA/NaN; check that it is defined over the whole domain (lower, upper).")
    }
    if (any(fx < 0)) {
      stop("ars: the density function returned a negative value; it must be a valid (unnormalized) density.")
    }
    log(fx)
  }
}

## Numerical derivative of h at (possibly vector) x via central finite
## differences, with the step size shrunk near finite domain boundaries
## so that h is never evaluated outside (lower, upper).
.ars_h_prime <- function(h, x, lower, upper, rel_step = 1e-5) {
  step <- pmax(abs(x) * rel_step, 1e-6)
  if (is.finite(lower)) step <- pmin(step, (x - lower) / 4)
  if (is.finite(upper)) step <- pmin(step, (upper - x) / 4)
  step <- pmax(step, .Machine$double.eps * 100)
  xr <- x + step
  xl <- x - step
  (h(xr) - h(xl)) / (xr - xl)
}

## =================================================================
## 3. Initial abscissae selection
## =================================================================

.ars_default_initial_points <- function(lower, upper) {
  if (is.finite(lower) && is.finite(upper)) {
    lower + (upper - lower) * c(0.25, 0.75)
  } else if (is.finite(lower)) {
    lower + c(0.5, 2)
  } else if (is.finite(upper)) {
    upper - c(2, 0.5)
  } else {
    c(-1, 1)
  }
}

## Finds a valid, sorted set of starting abscissae such that (when the
## domain is unbounded) the log-density derivative is positive at the
## leftmost point and negative at the rightmost point -- the condition
## required for the upper hull to have finite integral in each tail.
.ars_initial_abscissae <- function(hprime_fn, lower, upper, initial_points) {
  x <- if (is.null(initial_points)) {
    .ars_default_initial_points(lower, upper)
  } else {
    sort(unique(initial_points))
  }

  if (!is.finite(lower)) {
    attempts <- 0L
    while (hprime_fn(x[1]) <= 0 && attempts < 50L) {
      x <- c(x[1] - abs(x[1]) - 1, x)
      attempts <- attempts + 1L
    }
    if (hprime_fn(x[1]) <= 0) {
      stop("ars: could not find a starting point with positive log-density slope on the left tail (domain unbounded below). The density may not be log-concave, or supply 'initial_points'.")
    }
  }

  if (!is.finite(upper)) {
    attempts <- 0L
    while (hprime_fn(x[length(x)]) >= 0 && attempts < 50L) {
      x <- c(x, x[length(x)] + abs(x[length(x)]) + 1)
      attempts <- attempts + 1L
    }
    if (hprime_fn(x[length(x)]) >= 0) {
      stop("ars: could not find a starting point with negative log-density slope on the right tail (domain unbounded above). The density may not be log-concave, or supply 'initial_points'.")
    }
  }

  sort(unique(x))
}

## =================================================================
## 4. Log-concavity check
## =================================================================

## A log-concave h must have a non-increasing derivative. Given sorted
## abscissae and their h'(x) values, this raises an informative error
## the first time an increase (beyond numerical tolerance) is detected.
.ars_check_log_concave <- function(x, hp, tol) {
  if (length(x) < 2) return(invisible(TRUE))
  o <- order(x)
  x <- x[o]; hp <- hp[o]
  diffs <- diff(hp)
  scale <- pmax(1, abs(hp[-length(hp)]), abs(hp[-1]))
  bad <- which(diffs > tol * scale)
  if (length(bad) > 0) {
    i <- bad[1]
    stop(sprintf(
      "ars: the target density does not appear to be log-concave (the derivative of the log-density increased from %.6g at x=%.6g to %.6g at x=%.6g). Adaptive rejection sampling requires a log-concave target density.",
      hp[i], x[i], hp[i + 1], x[i + 1]
    ))
  }
  invisible(TRUE)
}

## =================================================================
## 5. Upper/lower hull construction
## =================================================================

## Intersection points z_1..z_{k-1} of consecutive tangent lines, plus
## the domain boundaries as z_0 and z_k.
.ars_compute_breakpoints <- function(x, hx, hpx, lower, upper) {
  k <- length(x)
  z <- numeric(k + 1)
  z[1] <- lower
  z[k + 1] <- upper
  if (k > 1) {
    for (i in seq_len(k - 1)) {
      denom <- hpx[i] - hpx[i + 1]
      if (abs(denom) < 1e-10) {
        z[i + 1] <- (x[i] + x[i + 1]) / 2
      } else {
        z[i + 1] <- (hx[i + 1] - hx[i] - x[i + 1] * hpx[i + 1] + x[i] * hpx[i]) / denom
      }
    }
  }
  z
}

## log of the integral of exp(tangent line at x_i) over [a, b], computed
## in a numerically stable way (anchored at whichever endpoint keeps the
## exponent from overflowing), so that infinite tails (a = -Inf or
## b = Inf) are handled without producing NaN.
.ars_segment_logA <- function(a, b, xi, hi, hpi, flat_tol = 1e-8) {
  if (abs(hpi) < flat_tol) {
    return(hi + log(b - a))
  }
  if (hpi > 0) {
    hpi * (b - xi) - log(hpi) + log(-expm1(hpi * (a - b)))
  } else {
    hpi * (a - xi) - log(-hpi) + log(-expm1(hpi * (b - a)))
  }
}

## Builds the full piecewise-linear upper hull (tangents) and the
## information needed to sample from it, from the current abscissae.
.ars_build_hull <- function(x, hx, hpx, lower, upper) {
  k <- length(x)
  z <- .ars_compute_breakpoints(x, hx, hpx, lower, upper)
  logA <- vapply(seq_len(k), function(i) {
    .ars_segment_logA(z[i], z[i + 1], x[i], hx[i], hpx[i])
  }, numeric(1))
  m <- max(logA)
  w <- exp(logA - m)
  cumw <- cumsum(w) / sum(w)
  list(x = x, h = hx, hp = hpx, z = z, logA = logA, cumw = cumw, k = k,
       lower = lower, upper = upper)
}

## =================================================================
## 6. Hull evaluation (upper hull u(x) and lower/squeezing hull l(x))
## =================================================================

.ars_upper_hull_value <- function(hull, xq) {
  i <- findInterval(xq, hull$z, rightmost.closed = TRUE)
  i <- max(1L, min(hull$k, i))
  hull$h[i] + hull$hp[i] * (xq - hull$x[i])
}

.ars_lower_hull_value <- function(hull, xq) {
  if (xq < hull$x[1] || xq > hull$x[hull$k]) return(-Inf)
  if (hull$k == 1) return(-Inf)
  i <- findInterval(xq, hull$x, rightmost.closed = TRUE)
  i <- max(1L, min(hull$k - 1L, i))
  x1 <- hull$x[i]; x2 <- hull$x[i + 1]
  h1 <- hull$h[i]; h2 <- hull$h[i + 1]
  ((x2 - xq) * h1 + (xq - x1) * h2) / (x2 - x1)
}

## =================================================================
## 7. Sampling from the piecewise-exponential upper hull
## =================================================================

## Inverse-CDF sample within one segment [a, b], where the segment's
## unnormalized density is exp(hpi * (t - xi) + hi). Anchored at
## whichever endpoint keeps exponents from overflowing.
.ars_sample_segment <- function(a, b, xi, hpi, u, flat_tol = 1e-8) {
  if (abs(hpi) < flat_tol) {
    return(a + u * (b - a))
  }
  if (hpi > 0) {
    b + log(u + (1 - u) * exp(hpi * (a - b))) / hpi
  } else {
    a + log((1 - u) + u * exp(hpi * (b - a))) / hpi
  }
}

.ars_sample_upper <- function(hull) {
  u1 <- runif(1)
  i <- findInterval(u1, c(0, hull$cumw), rightmost.closed = TRUE)
  i <- max(1L, min(hull$k, i))
  a <- hull$z[i]; b <- hull$z[i + 1]
  u2 <- runif(1)
  .ars_sample_segment(a, b, hull$x[i], hull$hp[i], u2)
}

## =================================================================
## 8. Main driver
## =================================================================

#' Adaptive rejection sampling for a log-concave density.
#'
#' @param n              Number of samples to draw (positive integer).
#' @param f               Function computing the (possibly unnormalized)
#'                        density, vectorized over its first argument
#'                        (e.g. dnorm, dexp, or a user expression).
#' @param lower, upper    Support of the density (may be -Inf / Inf).
#' @param initial_points  Optional numeric vector (length >= 2) of
#'                        starting abscissae within (lower, upper).
#' @param tol             Tolerance used by the log-concavity check.
#' @param max_iter        Maximum number of sampling iterations before
#'                        giving up (guards against infinite loops).
#' @param seed            Optional RNG seed for reproducibility.
#' @return A list with elements: samples, n_abscissae, n_evaluations,
#'         n_iterations.
ars <- function(n, f, lower = -Inf, upper = Inf, initial_points = NULL,
                 tol = 1e-6, max_iter = max(2000L, 200L * n), seed = NULL) {

  .ars_validate_inputs(n, f, lower, upper, initial_points, max_iter, tol)
  if (!is.null(seed)) set.seed(seed)
  n <- as.integer(round(n))

  h <- .ars_make_log_density(f)
  hp <- function(x) .ars_h_prime(h, x, lower, upper)

  x <- .ars_initial_abscissae(hp, lower, upper, initial_points)
  hx <- h(x)
  if (any(!is.finite(hx))) {
    stop("ars: the density is zero (or otherwise invalid) at the initial abscissae; supply 'initial_points' within the true support of the density.")
  }
  hpx <- hp(x)
  .ars_check_log_concave(x, hpx, tol)

  samples <- numeric(n)
  n_accepted <- 0L
  n_eval <- 0L
  iter <- 0L

  while (n_accepted < n) {
    iter <- iter + 1L
    if (iter > max_iter) {
      stop(sprintf(
        "ars: exceeded max_iter (%d) while trying to draw %d samples (only %d accepted so far). The density may not be log-concave, or the domain/initial points may need adjusting.",
        max_iter, n, n_accepted
      ))
    }

    hull <- .ars_build_hull(x, hx, hpx, lower, upper)
    xstar <- .ars_sample_upper(hull)
    w <- runif(1)

    uk <- .ars_upper_hull_value(hull, xstar)
    lk <- .ars_lower_hull_value(hull, xstar)

    if (is.finite(lk) && w <= exp(lk - uk)) {
      ## Squeeze test passed: accept without evaluating h.
      n_accepted <- n_accepted + 1L
      samples[n_accepted] <- xstar
      next
    }

    ## Squeeze test failed (or unavailable): evaluate the true density.
    hxstar <- h(xstar)
    n_eval <- n_eval + 1L

    if (is.finite(hxstar)) {
      if (w <= exp(hxstar - uk)) {
        n_accepted <- n_accepted + 1L
        samples[n_accepted] <- xstar
      }
      hpxstar <- hp(xstar)
      if (is.finite(hpxstar)) {
        x <- c(x, xstar); hx <- c(hx, hxstar); hpx <- c(hpx, hpxstar)
        o <- order(x)
        x <- x[o]; hx <- hx[o]; hpx <- hpx[o]
        .ars_check_log_concave(x, hpx, tol)
      }
    }
    ## else: hxstar is -Inf/invalid (outside true support) -- reject
    ## without updating the hull.
  }

  list(samples = samples, n_abscissae = length(x), n_evaluations = n_eval,
       n_iterations = iter)
}

## =================================================================
## 9. Formal test suite
## =================================================================

#' Runs a formal battery of tests for ars() and its internal modules,
#' printing "TEST_NAME: PASS"/"FAIL" lines with supporting statistics.
test <- function(seed = 20260813) {

  results <- list()
  .report <- function(name, ok, detail = "") {
    status <- if (isTRUE(ok)) "PASS" else "FAIL"
    if (nzchar(detail)) {
      cat(sprintf("%s: %s  (%s)\n", name, status, detail))
    } else {
      cat(sprintf("%s: %s\n", name, status))
    }
    results[[name]] <<- isTRUE(ok)
  }

  cat("=========================================================\n")
  cat(" Adaptive Rejection Sampling (Gilks & Wild, 1992) -- Tests\n")
  cat("=========================================================\n\n")

  ## ---------------------------------------------------------------
  cat("--- Standard Normal N(0,1) ---\n")
  set.seed(seed)
  res <- ars(3000, dnorm, lower = -Inf, upper = Inf)
  s <- res$samples
  m <- mean(s); sdv <- sd(s)
  ks <- suppressWarnings(ks.test(s, "pnorm"))
  ok <- abs(m) < 0.1 && abs(sdv - 1) < 0.1 && ks$p.value > 0.01
  cat(sprintf("  mean=%.4f (target 0), sd=%.4f (target 1), KS p-value=%.4f, evals/sample=%.2f\n",
              m, sdv, ks$p.value, res$n_evaluations / length(s)))
  .report("NORMAL_SAMPLING", ok, sprintf("mean=%.3f sd=%.3f", m, sdv))
  tryCatch(writeLines(as.character(s), "/app/normal_samples.txt"), error = function(e) NULL)

  ## ---------------------------------------------------------------
  cat("\n--- Exponential(rate=1) ---\n")
  set.seed(seed + 1)
  res2 <- ars(3000, function(x) dexp(x, rate = 1), lower = 0, upper = Inf)
  s2 <- res2$samples
  m2 <- mean(s2); sd2 <- sd(s2)
  ks2 <- suppressWarnings(ks.test(s2, "pexp", rate = 1))
  ok2 <- abs(m2 - 1) < 0.12 && abs(sd2 - 1) < 0.12 && ks2$p.value > 0.01
  cat(sprintf("  mean=%.4f (target 1), sd=%.4f (target 1), KS p-value=%.4f, evals/sample=%.2f\n",
              m2, sd2, ks2$p.value, res2$n_evaluations / length(s2)))
  .report("EXPONENTIAL_SAMPLING", ok2, sprintf("mean=%.3f sd=%.3f", m2, sd2))
  tryCatch(writeLines(as.character(s2), "/app/exponential_samples.txt"), error = function(e) NULL)

  ## ---------------------------------------------------------------
  cat("\n--- Gamma(shape=3, rate=2) [asymmetric, lower-bounded] ---\n")
  set.seed(seed + 2)
  res3 <- ars(3000, function(x) dgamma(x, shape = 3, rate = 2), lower = 0, upper = Inf)
  s3 <- res3$samples
  m3 <- mean(s3); sd3 <- sd(s3)
  true_m3 <- 3 / 2; true_sd3 <- sqrt(3) / 2
  ks3 <- suppressWarnings(ks.test(s3, "pgamma", shape = 3, rate = 2))
  ok3 <- abs(m3 - true_m3) < 0.1 && abs(sd3 - true_sd3) < 0.1 && ks3$p.value > 0.01
  cat(sprintf("  mean=%.4f (target %.4f), sd=%.4f (target %.4f), KS p-value=%.4f\n",
              m3, true_m3, sd3, true_sd3, ks3$p.value))
  .report("GAMMA_SAMPLING", ok3, sprintf("mean=%.3f sd=%.3f", m3, sd3))

  ## ---------------------------------------------------------------
  cat("\n--- Truncated Normal on [-2, 2] [bounded domain] ---\n")
  set.seed(seed + 3)
  res4 <- ars(3000, dnorm, lower = -2, upper = 2)
  s4 <- res4$samples
  ok4 <- all(s4 >= -2 & s4 <= 2) && abs(mean(s4)) < 0.1
  cat(sprintf("  mean=%.4f (target 0), sd=%.4f, all within bounds=%s\n",
              mean(s4), sd(s4), all(s4 >= -2 & s4 <= 2)))
  .report("TRUNCATED_NORMAL_BOUNDS", ok4, sprintf("mean=%.3f sd=%.3f", mean(s4), sd(s4)))

  ## ---------------------------------------------------------------
  cat("\n--- Input validation: negative sample count ---\n")
  ok5 <- tryCatch({ ars(-5, dnorm); FALSE }, error = function(e) TRUE)
  .report("VALIDATION_NEGATIVE_N", ok5)

  cat("--- Input validation: non-integer sample count ---\n")
  ok6 <- tryCatch({ ars(3.5, dnorm); FALSE }, error = function(e) TRUE)
  .report("VALIDATION_NONINTEGER_N", ok6)

  cat("--- Input validation: invalid domain (lower >= upper) ---\n")
  ok7 <- tryCatch({ ars(10, dnorm, lower = 5, upper = 1); FALSE }, error = function(e) TRUE)
  .report("VALIDATION_BAD_DOMAIN", ok7)

  cat("--- Input validation: non-function density ---\n")
  ok8 <- tryCatch({ ars(10, "not_a_function"); FALSE }, error = function(e) TRUE)
  .report("VALIDATION_NON_FUNCTION", ok8)

  cat("--- Input validation: initial_points outside domain ---\n")
  ok9 <- tryCatch({
    ars(10, function(x) dexp(x, 1), lower = 0, upper = Inf, initial_points = c(-1, 2))
    FALSE
  }, error = function(e) TRUE)
  .report("VALIDATION_BAD_INITIAL_POINTS", ok9)

  ## ---------------------------------------------------------------
  cat("\n--- Log-concavity check: bimodal mixture (should error) ---\n")
  bimodal <- function(x) 0.5 * dnorm(x, -4, 1) + 0.5 * dnorm(x, 4, 1)
  ok10 <- tryCatch({
    ars(1000, bimodal, lower = -Inf, upper = Inf, initial_points = c(-6, -2, 2, 6))
    FALSE
  }, error = function(e) {
    cat(sprintf("  caught expected error: %s\n", conditionMessage(e)))
    TRUE
  })
  .report("LOG_CONCAVITY_CHECK_BIMODAL", ok10)

  cat("\n--- Log-concavity check: Student-t (heavy, convex tails; should error) ---\n")
  ok11 <- tryCatch({
    ars(1000, function(x) dt(x, df = 3), lower = -Inf, upper = Inf,
        initial_points = c(-8, -0.5, 0.5, 8))
    FALSE
  }, error = function(e) {
    cat(sprintf("  caught expected error: %s\n", conditionMessage(e)))
    TRUE
  })
  .report("LOG_CONCAVITY_CHECK_STUDENT_T", ok11)

  ## ---------------------------------------------------------------
  cat("\n--- Module test: hull bracketing property (u(x) >= h(x) >= l(x)) ---\n")
  h <- .ars_make_log_density(dnorm)
  hp <- function(x) .ars_h_prime(h, x, -Inf, Inf)
  xa <- c(-1.5, -0.3, 0.4, 1.2)
  hxa <- h(xa); hpxa <- hp(xa)
  hull <- .ars_build_hull(xa, hxa, hpxa, -Inf, Inf)
  probe <- seq(-3, 3, length.out = 200)
  uvals <- vapply(probe, function(q) .ars_upper_hull_value(hull, q), numeric(1))
  lvals <- vapply(probe, function(q) .ars_lower_hull_value(hull, q), numeric(1))
  hvals <- h(probe)
  ok12 <- all(uvals >= hvals - 1e-8) && all(lvals[is.finite(lvals)] <= hvals[is.finite(lvals)] + 1e-8)
  cat(sprintf("  max(h - u) = %.2e (should be <= 0), max(l - h) among finite l = %.2e (should be <= 0)\n",
              max(hvals - uvals), max((lvals - hvals)[is.finite(lvals)])))
  .report("HULL_BRACKETING_PROPERTY", ok12)

  cat("--- Module test: log-concavity checker flags an increasing derivative ---\n")
  ok13 <- tryCatch({
    .ars_check_log_concave(c(0, 1, 2), c(1, 1.5, 0.5), tol = 1e-6)
    FALSE
  }, error = function(e) TRUE)
  ok13b <- tryCatch({
    .ars_check_log_concave(c(0, 1, 2), c(1, 0.5, -0.5), tol = 1e-6)
    TRUE
  }, error = function(e) FALSE)
  .report("CONCAVITY_CHECKER_UNIT_TEST", ok13 && ok13b)

  ## ---------------------------------------------------------------
  cat("\n=========================================================\n")
  n_pass <- sum(unlist(results))
  n_total <- length(results)
  cat(sprintf("SUMMARY: %d / %d tests passed.\n", n_pass, n_total))
  cat("=========================================================\n")

  invisible(results)
}

